// Vtable is a static, per-class structure.
// Vtable_Base = { &Base::action, &Base::~Base }
class Base {
public:
    // Implicit vptr* added here
    virtual void action() {}
    virtual ~Base() {}
};

// Vtable_Derived = { &Derived::action, &Base::~Base }
class Derived : public Base {
    void action() override {}
};

// Runtime dispatch uses the object's vptr
// to lookup the function address in the Vtable.
Base* obj_d = new Derived();
obj_d->action(); // Dispatch resolved at runtime
delete obj_d;
// Base layout: [vptr] [member data...]
